function box(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
function circle(x,y,r,c){ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function text(s,x,y,size=8,color='#fff',align='left'){ctx.fillStyle=color;ctx.font=`bold ${size}px ui-rounded,system-ui,sans-serif`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function drawKitty(x,y,scale=1,cheer=false){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(scale,scale);const dio=save.character==='diovana';if(dio){ // curly hair silhouette and strawberry-colored outfit
circle(6,4,8,'#5a332b');circle(1,2,4,'#40241f');circle(11,1,4,'#40241f');circle(1,7,3,'#6a3b2b');circle(12,7,3,'#6a3b2b');box(0,0,13,10,'#4d2b24');circle(6,5,5,'#8a503e');box(2,13,9,7,'#f08349');box(1,14,11,4,'#ef5f73');circle(3,5,1,'#231d24');circle(9,5,1,'#231d24');box(5,7,2,1,'#f6b841');box(10,0,3,2,'#ffb0ca');box(-1,15,3,2,'#ffcf61');}
else{ // white kitty face, classic bow and whiskers
box(1,3,12,10,'#fffdf7');box(2,1,3,4,'#fffdf7');box(10,1,3,4,'#fffdf7');box(3,5,8,6,'#fffdf7');box(4,7,1,2,'#20202d');box(9,7,1,2,'#20202d');box(7,8,2,1,'#ffd34e');box(0,9,4,1,'#4c4350');box(-1,11,5,1,'#4c4350');box(10,9,4,1,'#4c4350');box(10,11,5,1,'#4c4350');box(0,2,3,3,'#ff4775');box(-1,3,2,2,'#ff4775');box(2,3,2,2,'#ff4775');circle(1,3,1,'#ff88a8');box(2,13,10,6,'#fffdf7');box(3,18,3,2,'#ff789d');box(9,18,3,2,'#ff789d');box(5,12,4,2,'#e94d78');}
if(cheer){box(2,0,2,3,'#ffc83f');box(11,-1,2,3,'#ffc83f')}ctx.restore()}
function sky(){let wc=worlds[world];box(0,0,W,H,wc[2]);for(let i=0;i<5;i++){let x=((i*83-camera*.18)%(W+50)+W+50)%(W+50)-20,y=17+(i*29)%44;circle(x,y,9,'#ffffffaa');circle(x+8,y+2,7,'#ffffffaa');circle(x-7,y+3,6,'#ffffffaa')}if(world===2){for(let i=0;i<8;i++){let x=(i*53-camera*.3)%W;circle(x,47+(i*37)%95,2,'#ffffff99')}}else{for(let i=0;i<5;i++){let x=(i*77-camera*.08)%W;circle(x,120+(i*11)%25,16,wc[3]+'77')}}}
function drawWorld(){sky(); // ground and distant decorations
for(const s of level.solids){if(s.type==='removed')continue;let x=s.x*T-camera;if(x<-20||x>W+20)continue;if(s.type==='ground'){box(x,11*T,T,2*T,worlds[world][3]);box(x,11*T,T,3,'#9bdf83');box(x+2,11*T+5,3,3,'#fff6b8');if(s.x%5===0){box(x+5,11*T-5,3,5,'#58b56c');circle(x+7,11*T-7,4,world===5?'#b49fd8':'#ffb1d0')}}else{box(x,s.y*T,s.w*T,8,s.type==='question'?'#ffcd68':'#c47b89');box(x+1,s.y*T+2,s.w*T-2,5,s.type==='question'?'#ffe89a':'#e9a1a7');if(s.type==='question')text('?',x+5,s.y*T+7,7,'#b36057');else{box(x+3,s.y*T+4,2,1,'#a3566b');box(x+10,s.y*T+4,2,1,'#a3566b')}}}
for(const p of level.platforms){let px=p.x-camera,py=p.base+Math.sin(frame*.05+p.phase)*10;if(px>-40&&px<W+20){box(px,py,p.w,6,'#f6a8cc');box(px+2,py+2,p.w-4,2,'#ffe7f1')}}
for(const it of level.items){if(it.got)continue;let x=it.x-camera,y=it.y+Math.sin(frame*.09+it.x)*2;if(x>-10&&x<W+10){if(it.kind==='berry'){circle(x,y,5,'#ed5c85');box(x-1,y-7,3,3,'#62b96c');circle(x-1,y,1,'#ffe8a6')}else if(it.kind==='star'){text('★',x,y+3,12,'#ffd451','center')}else{text('♥',x,y+3,11,'#ff759b','center')}}}
for(const e of level.enemies){if(!e.alive)continue;let x=e.x-camera;if(x<-20||x>W+20)continue;if(e.type==='boss'){circle(x+8,e.y+8,11,'#9e5270');circle(x+4,e.y+7,2,'#fff');circle(x+12,e.y+7,2,'#fff');box(x+4,e.y-2,3,4,'#ff6e9a');box(x+10,e.y-2,3,4,'#ff6e9a');text('♥'.repeat(Math.max(0,e.hp)),x+8,e.y-7,7,'#ffdf55','center')}else{circle(x+6,e.y+6,7,e.type==='fly'?'#b17add':'#e991b2');circle(x+4,e.y+5,1,'#433344');circle(x+9,e.y+5,1,'#433344');box(x+1,e.y+10,3,2,'#7c536e');box(x+9,e.y+10,3,2,'#7c536e');if(e.type==='fly'){box(x-1,e.y,4,3,'#fff9');box(x+10,e.y,4,3,'#fff9')}}}
// goal flag
let gx=level.goal*T-camera;box(gx,7*T,2,4*T,'#fff');box(gx+2,7*T,13,9,'#ff6291');text('✿',gx+8,7*T+7,6,'#fff','center');
if(player){if(player.inv%8<4){drawKitty(player.x-camera,player.y,1,player.ground&&Math.abs(player.vx)>1&&frame%25<8)}for(const p of particles){circle(p.x-camera,p.y,p.r,p.c)}}
// overlay terrain hint and level title
box(0,0,W,13,'#fff8');text(`${worlds[world][0]} ${worlds[world][1]}`,5,9,7,'#783c5a');text(`${stage+1}/12`,W-5,9,7,'#783c5a','right')}
function intersects(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function getSolidRects(){const arr=[];for(const s of level.solids){if(s.type==='ground')arr.push({x:s.x*T,y:11*T,w:T,h:2*T});else if(s.type!=='removed')arr.push({x:s.x*T,y:s.y*T,w:s.w*T,h:8})}for(const p of level.platforms){let py=p.base+Math.sin(frame*.05+p.phase)*10;arr.push({x:p.x,y:py,w:p.w,h:6,oneway:true})}return arr}
function takeHit(){if(player.inv>0)return;player.inv=100;player.power=0;player.vy=-3;player.vx=-player.facing*1.5;save.lives--;persist();setHUD();showMessage(save.lives>0?'Opa! Respire e tente de novo 💖':'Última chance!');if(save.lives<0){save.lives=5;persist();player.x=2*T;player.y=5*T}}
function update(dt){frame++;if(mode!=='game'||paused)return;if(noticeTimer>0&&!--noticeTimer)document.querySelector('#message').style.opacity=0;player.anim++;
const accel=keys.run?.32:.22,max=keys.run?2.45:1.55;if(keys.left){player.vx-=accel;player.facing=-1}else if(keys.right){player.vx+=accel;player.facing=1}else player.vx*=.78;player.vx=clamp(player.vx,-max,max);if(keys.jump&&player.ground){player.vy=keys.run?-5.7:-4.65;player.ground=false;keys.jump=false}player.vy=Math.min(5.5,player.vy+.23);let oldY=player.y;player.x+=player.vx;for(const s of getSolidRects())if(!s.oneway&&intersects(player,s)){if(player.vx>0)player.x=s.x-player.w;else if(player.vx<0)player.x=s.x+s.w;player.vx=0}player.y+=player.vy;player.ground=false;
for(const s of getSolidRects()){if(intersects(player,s)){if(player.vy>=0&&oldY+player.h<=s.y+3){player.y=s.y-player.h;player.vy=0;player.ground=true}else if(player.vy<0&&!s.oneway){player.y=s.y+s.h;player.vy=0;if(s.y<11*T){const b=level.solids.find(q=>q.type!=='ground'&&q.x*T===s.x&&q.y*T===s.y);if(b?.type==='question'){b.type='used';level.items.push({x:b.x*T+8,y:b.y*T-8,kind:'heart',got:false})}else if(b?.type==='brick')b.type='used'}}}}
if(player.y>H+20){takeHit();player.x=Math.max(2*T,player.x-20);player.y=5*T;player.vy=0}player.x=clamp(player.x,0,(level.length-1)*T);if(player.inv>0)player.inv--;
for(const it of level.items){if(!it.got&&intersects(player,{x:it.x-4,y:it.y-5,w:9,h:11})){it.got=true;if(it.kind==='berry'){save.berries++;if(save.berries%30===0)save.lives++}else if(it.kind==='star')save.stars++;else player.power=Math.min(2,player.power+1);persist();setHUD();for(let i=0;i<5;i++)particles.push({x:it.x,y:it.y,vx:rand(2)-1,vy:-rand(2),r:2+rand(2),c:'#ffe37a',life:25})}}
for(const e of level.enemies){if(!e.alive)continue;e.x+=e.dir*e.speed;if(Math.abs(e.x-e.home)>38)e.dir*=-1;if(e.type==='boss')e.y=9*T+Math.sin(frame*.06)*6;if(intersects(player,{x:e.x,y:e.y,w:e.type==='boss'?20:13,h:e.type==='boss'?21:13})){if(player.vy>0&&oldY+player.h<e.y+7){if(e.type==='boss'){e.hp--;if(e.hp<=0)e.alive=false;player.vy=-4;showMessage('Pof! Mais uma vez!')}else e.alive=false;player.vy=-3.6;save.stars+=e.type==='boss'?1:0;setHUD()}else if(e.type==='boss'&&player.inv===0)takeHit();else if(player.inv===0)takeHit()}}
for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.08;p.life--}particles=particles.filter(p=>p.life>0);camera=clamp(player.x-110,0,level.length*T-W);
if(player.x>=level.goal*T){if(world===7&&stage===0)level.secret=true;finish()}
// Hidden trail: jump above the canopy at a marked point in the first forest stage
if(world===3&&stage===4&&!level.secret&&player.x>70*T&&player.y<4*T){level.secret=true;save.diovana=true;persist();showMessage('Uma passagem secreta! Diovana Caroline desbloqueada 🍊')}
}

